class Solution {
    public List<Integer> powerfulIntegers(int x, int y, int bound) {

        int a = x == 1 ? bound : (int) (Math.log(bound) / Math.log(x));
        int b = y == 1 ? bound : (int) (Math.log(bound) / Math.log(y));

        HashSet<Integer> powerfulIntegers = new HashSet<Integer>();

        for (int i = 0; i <= a; i++) {
            for (int j = 0; j <= b; j++) {

                int value = (int) Math.pow(x, i) + (int) Math.pow(y, j);

                if (value <= bound) {
                    powerfulIntegers.add(value);
                }

                // No point in considering other powers of "1".
                if (y == 1) {
                    break;
                }
            }

            if (x == 1) {
                break;
            }
        }

        return new ArrayList<Integer>(powerfulIntegers);
    }
}

class Solution:
    def powerfulIntegers(self, x: int, y: int, bound: int) -> List[int]:

        a = bound if x == 1 else int(log(bound, x))
        b = bound if y == 1 else int(log(bound, y))

        powerful_integers = set([])

        for i in range(a + 1):
            for j in range(b + 1):

                value = x**i + y**j

                if value <= bound:
                    powerful_integers.add(value)

                if y == 1:
                    break

            if x == 1:
                break

        return list(powerful_integers)

class Solution(object):
    def powerfulIntegers(self, x, y, bound):
        """
        :type x: int
        :type y: int
        :type bound: int
        :rtype: List[int]
        """
        x_list = []
        y_list = []
        if x == 1:
            if bound > 1:
                x_list = [1]
        else:
            cur = 1
            while cur < bound:
                x_list.append(cur)
                cur = cur * x
        if y == 1:
            if bound > 1:
                y_list = [1]
        else:
            cur = 1
            while cur < bound:
                y_list.append(cur)
                cur = cur * y
        ans = []
        for cur_x in x_list:
            for cur_y in y_list:
                cur_ans = cur_x + cur_y
                if cur_ans <= bound:
                    ans.append(cur_x + cur_y)
                else:
                    break
        ans = list(set(ans))
        return ans
